CREATE SCHEMA IF NOT EXISTS exchange;
CREATE TABLE exchange.schema_version (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), version integer NOT NULL CHECK(version > 0));
INSERT INTO exchange.schema_version VALUES (true,1);
CREATE TABLE exchange.wallets (owner_id text PRIMARY KEY, balance bigint NOT NULL DEFAULT 0 CHECK(balance >= 0), reserved bigint NOT NULL DEFAULT 0 CHECK(reserved >= 0 AND reserved <= balance), revision bigint NOT NULL DEFAULT 0 CHECK(revision >= 0));
CREATE TABLE exchange.wallet_entries (owner_id text NOT NULL REFERENCES exchange.wallets(owner_id), sequence bigint NOT NULL CHECK(sequence > 0), operation_id text NOT NULL, delta bigint NOT NULL, flow_class text NOT NULL, code text NOT NULL, PRIMARY KEY(owner_id,sequence));
CREATE TABLE exchange.operations (operation_id text PRIMARY KEY, fingerprint text NOT NULL, receipt jsonb NOT NULL);
CREATE TABLE exchange.listings (id text PRIMARY KEY, seller_id text NOT NULL, escrow_id text NOT NULL, item_id text NOT NULL, quantity bigint NOT NULL CHECK(quantity > 0), price bigint NOT NULL CHECK(price > 0), fee bigint NOT NULL CHECK(fee >= 0), state text NOT NULL CHECK(state IN ('active','pending','sold','cancelled')), revision bigint NOT NULL DEFAULT 0 CHECK(revision >= 0), settlement_id text UNIQUE);
CREATE TABLE exchange.settlements (operation_id text PRIMARY KEY, fingerprint text NOT NULL, kind text NOT NULL CHECK(kind IN ('trade','listing')), subject_id text NOT NULL, payer_id text, payee_id text, amount bigint NOT NULL CHECK(amount >= 0), fee bigint NOT NULL CHECK(fee >= 0 AND fee <= amount), deliveries jsonb NOT NULL, state text NOT NULL CHECK(state IN ('pending','committed','compensated')), receipt jsonb NOT NULL);
CREATE UNIQUE INDEX exchange_pending_subject ON exchange.settlements(kind,subject_id) WHERE state IN ('pending','committed');
